/** NotAdmin: Caller is not the board admin */
export const FULL_SHANK_ERROR__NOT_ADMIN = 0x0 // 0
/** BoardAlreadyInitialized: Board has already been initialized */
export const FULL_SHANK_ERROR__BOARD_ALREADY_INITIALIZED = 0x1 // 1
/** BoardNotInitialized: Board has not been initialized */
export const FULL_SHANK_ERROR__BOARD_NOT_INITIALIZED = 0x2 // 2
