export const FULL_SHANK_ERROR__PROFILE_NOT_FOUND = 0x4 // 4
/** NotAuthor: Caller is not the post author */
export const FULL_SHANK_ERROR__NOT_AUTHOR = 0x5 // 5
/** PostAlreadyDeleted: Post has already been deleted */
export const FULL_SHANK_ERROR__POST_ALREADY_DELETED = 0x6 // 6
/** UserSuspended: User account is suspended */
export const FULL_SHANK_ERROR__USER_SUSPENDED = 0x7 // 7
/** NumericalOverflow: Numerical overflow */
export const FULL_SHANK_ERROR__NUMERICAL_OVERFLOW = 0x8 // 8

export type FullShankError =
	| typeof FULL_SHANK_ERROR__BOARD_ALREADY_INITIALIZED
	| typeof FULL_SHANK_ERROR__BOARD_NOT_INITIALIZED
	| typeof FULL_SHANK_ERROR__NOT_ADMIN
	| typeof FULL_SHANK_ERROR__NOT_AUTHOR
	| typeof FULL_SHANK_ERROR__NUMERICAL_OVERFLOW
	| typeof FULL_SHANK_ERROR__POST_ALREADY_DELETED
	| typeof FULL_SHANK_ERROR__PROFILE_ALREADY_EXISTS
